package webapi

import (
	"fmt"
	"strings"
	"sync"

	"github.com/grafana/sobek"
)

// emojiProperty is one ECMAScript property of strings (emoji_tables.go,
// generated by internal/genemoji from Unicode's emoji data): its single
// code points as [lo, hi] ranges and its strings of two or more code
// points.
type emojiProperty struct {
	ranges  []rune
	strings []string
}

// classBodies caches each property's ranges as a u-mode class body.
var classBodies sync.Map // name -> string

// classBody is p's single code points as a u-mode character class body
// (\u{lo}-\u{hi}...).
func classBody(name string, p emojiProperty) string {
	if v, ok := classBodies.Load(name); ok {
		return v.(string)
	}
	var b strings.Builder
	for i := 0; i+1 < len(p.ranges); i += 2 {
		lo, hi := p.ranges[i], p.ranges[i+1]
		fmt.Fprintf(&b, `\u{%x}`, lo)
		if hi > lo {
			fmt.Fprintf(&b, `-\u{%x}`, hi)
		}
	}
	classBodies.Store(name, b.String())
	return b.String()
}

// installStringProperties gives the prelude's RegExp the v flag's
// properties of strings (js/src/unicodesets.ts): stringProperty(name) is
// { content, strings } (a class body for the single code points, and the
// longer strings), or undefined for other names.
func (h *host) installStringProperties() {
	h.set("stringProperty", func(name string) sobek.Value {
		p, ok := emojiProperties[name]
		if !ok {
			return sobek.Undefined()
		}
		strs := make([]any, len(p.strings))
		for i, s := range p.strings {
			strs[i] = s
		}
		return h.vm.ToValue(map[string]any{"content": classBody(name, p), "strings": strs})
	})
}
